  `Etat2` tinyint DEFAULT '0',
  `created_at` date DEFAULT NULL,
  `updated_at` time NOT NULL,
  `TVA` double NOT NULL,
  `num_facture` varchar(50) NOT NULL DEFAULT '0',
  `serveur` int DEFAULT NULL,
  `client` int NOT NULL DEFAULT '0',
  `modeReglement` tinyint NOT NULL DEFAULT '1',
  `taxSpecific` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`Num`)
